pub fn set_input_pose(&mut self, local: &[RigTransform]) -> Result<(), String> {
    if local.len() != self.bones.len() {
        return Err("rig input pose size does not match the hierarchy".to_owned());
    }
    for (pose, &transform) in self.current.iter_mut().zip(local) {
        pose.local = transform;
        pose.dirty = Some(RigSpace::Global);
    }
    Ok(())
}

fn pose(&mut self, index: usize, initial: bool) -> Result<&mut BonePose, String> {
    if initial {
        &mut self.initial
    } else {
        &mut self.current
    }
    .get_mut(index)
    .ok_or_else(|| "rig bone index is invalid".to_owned())
}

pub fn transform(
    &mut self,
    index: usize,
    space: RigSpace,
    initial: bool,
) -> Result<RigTransform, String> {
    let pose = *self.pose(index, initial)?;
    if pose.dirty == Some(space) {
        let parent = if let Some(parent) = self.bones[index].parent {
            self.transform(parent, RigSpace::Global, initial)?
        } else {
            RigTransform::default()
        };
        let transform = match space {
            RigSpace::Local => {
                let mut local = pose.global.relative(parent);
                if local.scale.abs().min_element() <= 1e-8
                    && parent.scale.abs().min_element() <= 1e-8
                {
                    local.translation = pose.local.translation;
                    local.scale = pose.local.scale;
                }
                local
            }
            RigSpace::Global => pose.local.global(parent),
        };
        let pose = self.pose(index, initial)?;
        match space {
            RigSpace::Local => pose.local = transform,
            RigSpace::Global => pose.global = transform,
        }

pub fn source_input_data(ctx: &NodeContext, key: &str) -> Option<DataValue> {
    let arena = ctx.graph_context.context_arena.get_ref();
    let state = arena
        .get_toplevel()
        .node_states
        .get::<SourceInstanceProperties>(NodeId::default(), StateKey::Default)
        .ok();
    source_property_value(
        state,
        ctx.graph_context.frame_index(),
        key,
        ctx.graph_context
            .global_input_data
            .get(&format!("source_frame_input.{key}")),
    )
    .or_else(|| ctx.graph_context.global_input_data.get(key))
    .cloned()
}

fn source_property_value<'a>(
    state: Option<&'a SourceInstanceProperties>,
    frame: u64,
    key: &str,
    input: Option<&'a DataValue>,
) -> Option<&'a DataValue> {
    if state.is_none_or(|state| state.write_frames.get(key) != Some(&frame)) && input.is_some() {
        return input;
    }
    state.and_then(|state| state.values.get(key)).or(input)
}

pub fn set_source_frame_input(
    player: &mut bevy_animation_graph::core::animation_graph_player::AnimationGraphPlayer,
    key: &str,
    value: impl Into<DataValue>,
) {
    player.set_global_input_data(format!("source_frame_input.{key}"), value);
}

pub fn source_player_property<'a>(
    player: &'a bevy_animation_graph::core::animation_graph_player::AnimationGraphPlayer,
    key: &str,
) -> Option<&'a DataValue> {
    let arena = player.get_context_arena();
    let state = arena.and_then(|arena| {
        arena
            .get_toplevel()
            .node_states
            .get::<SourceInstanceProperties>(NodeId::default(), StateKey::Default)
            .ok()
    });
    source_property_value(
        state,
        arena.map_or(0, |arena| arena.frame_index()),
        key,
        player.get_global_input_data(format!("source_frame_input.{key}")),
    )
}
